745	void LRUFileCache::removeIfReleasable(bool remove_persistent_files)
746	{
747	    /// Try remove all cached files by cache_base_path.
748	    /// Only releasable file segments are evicted.
749	    /// `remove_persistent_files` defines whether non-evictable by some criteria files
750	    /// (they do not comply with the cache eviction policy) should also be removed.
751	
752	    std::lock_guard cache_lock(mutex);
753	
754	    std::vector<FileSegment *> to_remove;
755	    for (auto it = queue.begin(); it != queue.end();)
756	    {
757	        const auto & [key, offset, size, _] = *it++;
758	        auto * cell = getCell(key, offset, cache_lock);
759	        if (!cell)
760	            throw Exception(
761	                ErrorCodes::LOGICAL_ERROR,
762	                "Cache is in inconsistent state: LRU queue contains entries with no cache cell");
763	
764	        if (cell->releasable())
765	        {
766	            auto file_segment = cell->file_segment;
767	            if (file_segment
768	                && (!file_segment->isPersistent()
769	                    || remove_persistent_files
770	                    || allow_to_remove_persistent_segments_from_cache_by_default))
771	            {
772	                std::lock_guard segment_lock(file_segment->mutex);
773	                file_segment->detach(cache_lock, segment_lock);
774	                remove(file_segment->key(), file_segment->offset(), cache_lock, segment_lock);
775	            }
776	        }
777	    }
778	
779	    /// Remove all access information.
780	    records.clear();
781	    stash_queue.removeAll(cache_lock);
782	
783	#ifndef NDEBUG
784	    assertCacheCorrectness(cache_lock);
785	#endif
